/**
 * ============================================================================
 * COMPARATIVE CLIENT-SIDE BENCHMARK AND TIME SERIES DATA UNIFICATION
 * ============================================================================
 * 
 * DESCRIPTION:
 * Reads output files generated by the two isolated Node.js processes:
 *   1. benchmark_client_ecdsa.js   -> results_client_ecdsa.json / timeseries_client_ecdsa.json
 *   2. benchmark_client_hybrid.js  -> results_client_hybrid.json / timeseries_client_hybrid.json
 * 
 * WHAT IT DOES:
 * - Unifies time series data into a single table aligned by iteration.
 * - Consolidates total accumulated times (KeyGen, Sign, Verify).
 * - Generates final output files: results_data.json, timeseries_data.json, and data.js.
 * - Prints formatted comparative tables to the console!
 */

const path = require('path');
const fs = require('fs');

/**
 * Unifies benchmark results from isolated ECDSA and Hybrid PQC runs and produces consolidated JSON/JS output files.
 */
function runComparison() {
  console.log("==========================================================================");
  console.log(" COMPARATIVE CLIENT-SIDE BENCHMARK (CONSOLIDATION OF ISOLATED DATA)");
  console.log("==========================================================================");

  const ecdsaSummaryPath = path.join(__dirname, 'results_client_ecdsa.json');
  const hybridSummaryPath = path.join(__dirname, 'results_client_hybrid.json');
  const ecdsaTsPath = path.join(__dirname, 'timeseries_client_ecdsa.json');
  const hybridTsPath = path.join(__dirname, 'timeseries_client_hybrid.json');

  if (!fs.existsSync(ecdsaSummaryPath) || !fs.existsSync(hybridSummaryPath)) {
    console.error("Isolated benchmark files not found!");
    console.error("Run the two isolated benchmark scripts first in your terminal:");
    console.error("  1) node --expose-gc --max-old-space-size=4096 benchmark_client_ecdsa.js");
    console.error("  2) node --expose-gc --max-old-space-size=4096 benchmark_client_hybrid.js");
    process.exit(1);
  }

  const ecdsaRes = JSON.parse(fs.readFileSync(ecdsaSummaryPath, 'utf8'));
  const hybridRes = JSON.parse(fs.readFileSync(hybridSummaryPath, 'utf8'));
  const ecdsaTs = JSON.parse(fs.readFileSync(ecdsaTsPath, 'utf8'));
  const hybridTs = JSON.parse(fs.readFileSync(hybridTsPath, 'utf8'));

  // --------------------------------------------------------------------------
  // 1. TIME SERIES DATA UNIFICATION (timeseries_data.json)
  // --------------------------------------------------------------------------
  const unifiedTimeSeries = [];
  const maxLen = Math.max(ecdsaTs.length, hybridTs.length);

  for (let i = 0; i < maxLen; i++) {
    const e = ecdsaTs[i] || {};
    const h = hybridTs[i] || {};
    unifiedTimeSeries.push({
      iteration: e.iteration || h.iteration || (i + 1) * 20,
      
      // KeyGen Metrics
      keyGenEcdsaMs: e.keyGenEcdsaMs,
      keyGenEcdsaCpuMs: e.keyGenEcdsaCpuMs,
      keyGenEcdsaRamKb: e.keyGenEcdsaRamKb,

      keyGenHybridMs: h.keyGenHybridMs,
      keyGenHybridCpuMs: h.keyGenHybridCpuMs,
      keyGenHybridRamKb: h.keyGenHybridRamKb,

      // Signing Metrics
      signEcdsaMs: e.signEcdsaMs,
      signEcdsaCpuMs: e.signEcdsaCpuMs,
      signEcdsaRamKb: e.signEcdsaRamKb,

      signHybridMs: h.signHybridMs,
      signHybridCpuMs: h.signHybridCpuMs,
      signHybridRamKb: h.signHybridRamKb,

      // Verification Metrics
      verifyEcdsaMs: e.verifyEcdsaMs,
      verifyEcdsaCpuMs: e.verifyEcdsaCpuMs,
      verifyEcdsaRamKb: e.verifyEcdsaRamKb,

      verifyHybridMs: h.verifyHybridMs,
      verifyHybridCpuMs: h.verifyHybridCpuMs,
      verifyHybridRamKb: h.verifyHybridRamKb
    });
  }

  // --------------------------------------------------------------------------
  // 2. CONSOLIDATE COMPARATIVE SUMMARY REPORT (results_data.json)
  // --------------------------------------------------------------------------
  const results = {
    metadata: {
      iterations: ecdsaRes.metadata.iterations,
      timestamp: new Date().toISOString(),
      nodeVersion: process.version,
      platform: process.platform,
      processIsolated: true
    },
    payloadSizes: {
      ecdsaPubKeyBytes: ecdsaRes.payloadSizes.ecdsaPubKeyBytes,
      mldsaPubKeyBytes: hybridRes.payloadSizes.mldsaPubKeyBytes,
      hybridPubKeyBytes: hybridRes.payloadSizes.hybridPubKeyBytes,
      ecdsaSigBytes: ecdsaRes.payloadSizes.ecdsaSigBytes,
      mldsaSigBytes: hybridRes.payloadSizes.mldsaSigBytes,
      hybridSigBytes: hybridRes.payloadSizes.hybridSigBytes,
      ecdsaEip1559TxBytes: ecdsaRes.payloadSizes.ecdsaEip1559TxBytes,
      hybridEip1559TxBytes: hybridRes.payloadSizes.hybridEip1559TxBytes
    },
    totalDurations: {
      ecdsa: ecdsaRes.totalDurations,
      hybrid: hybridRes.totalDurations
    },
    metrics: {
      keyGen: { ecdsa: ecdsaRes.metrics.keyGen, hybrid: hybridRes.metrics.keyGen },
      signing: { ecdsa: ecdsaRes.metrics.signing, hybrid: hybridRes.metrics.signing },
      verification: { ecdsa: ecdsaRes.metrics.verification, hybrid: hybridRes.metrics.verification }
    },
    cpuMetrics: {
      keyGen: { ecdsa: ecdsaRes.cpuMetrics.keyGen, hybrid: hybridRes.cpuMetrics.keyGen },
      signing: { ecdsa: ecdsaRes.cpuMetrics.signing, hybrid: hybridRes.cpuMetrics.signing },
      verification: { ecdsa: ecdsaRes.cpuMetrics.verification, hybrid: hybridRes.cpuMetrics.verification }
    },
    ramMetrics: {
      keyGen: { ecdsa: ecdsaRes.ramMetrics.keyGen, hybrid: hybridRes.ramMetrics.keyGen },
      signing: { ecdsa: ecdsaRes.ramMetrics.signing, hybrid: hybridRes.ramMetrics.signing },
      verification: { ecdsa: ecdsaRes.ramMetrics.verification, hybrid: hybridRes.ramMetrics.verification }
    }
  };

  // Display total accumulated time comparison table
  console.log("\n==========================================================================");
  console.log(` TOTAL ACCUMULATED TIME COMPARISON TABLE FOR A BLOCK OF ${ecdsaRes.metadata.iterations} ITERATIONS`);
  console.log("==========================================================================");
  console.table({
    "KeyGen (10,000x)": {
      "ECDSA (0x02) [ms]": ecdsaRes.totalDurations.keyGenTotalMs,
      "ECDSA [Seconds]": ecdsaRes.totalDurations.keyGenTotalSec,
      "Hybrid (0x42) [ms]": hybridRes.totalDurations.keyGenTotalMs,
      "Hybrid [Seconds]": hybridRes.totalDurations.keyGenTotalSec,
      "Difference (+Sec)": (hybridRes.totalDurations.keyGenTotalSec - ecdsaRes.totalDurations.keyGenTotalSec).toFixed(3)
    },
    "Signing (10,000x)": {
      "ECDSA (0x02) [ms]": ecdsaRes.totalDurations.signingTotalMs,
      "ECDSA [Seconds]": ecdsaRes.totalDurations.signingTotalSec,
      "Hybrid (0x42) [ms]": hybridRes.totalDurations.signingTotalMs,
      "Hybrid [Seconds]": hybridRes.totalDurations.signingTotalSec,
      "Difference (+Sec)": (hybridRes.totalDurations.signingTotalSec - ecdsaRes.totalDurations.signingTotalSec).toFixed(3)
    },
    "Verification (10,000x)": {
      "ECDSA (0x02) [ms]": ecdsaRes.totalDurations.verificationTotalMs,
      "ECDSA [Seconds]": ecdsaRes.totalDurations.verificationTotalSec,
      "Hybrid (0x42) [ms]": hybridRes.totalDurations.verificationTotalMs,
      "Hybrid [Seconds]": hybridRes.totalDurations.verificationTotalSec,
      "Difference (+Sec)": (hybridRes.totalDurations.verificationTotalSec - ecdsaRes.totalDurations.verificationTotalSec).toFixed(3)
    },
    "OVERALL (30,000 Operations)": {
      "ECDSA (0x02) [ms]": ecdsaRes.totalDurations.grandTotalMs,
      "ECDSA [Seconds]": ecdsaRes.totalDurations.grandTotalSec,
      "Hybrid (0x42) [ms]": hybridRes.totalDurations.grandTotalMs,
      "Hybrid [Seconds]": hybridRes.totalDurations.grandTotalSec,
      "Difference (+Sec)": (hybridRes.totalDurations.grandTotalSec - ecdsaRes.totalDurations.grandTotalSec).toFixed(3)
    }
  });

  console.log("\n==========================================================================");
  console.log(" LATENCY STATISTICAL TABLE PER OPERATION (IN MS)");
  console.log("==========================================================================");
  console.table({
    "KeyGen - ECDSA": results.metrics.keyGen.ecdsa,
    "KeyGen - Hybrid (ECDSA+MLDSA44)": results.metrics.keyGen.hybrid,
    "Sign - ECDSA EIP-1559": results.metrics.signing.ecdsa,
    "Sign - Hybrid EIP-1559": results.metrics.signing.hybrid,
    "Verify - ECDSA (DApp)": results.metrics.verification.ecdsa,
    "Verify - Hybrid (DApp)": results.metrics.verification.hybrid
  });

  const jsonSummaryPath = path.join(__dirname, 'results_data.json');
  const jsonTimeSeriesPath = path.join(__dirname, 'timeseries_data.json');
  const jsDataPath = path.join(__dirname, 'data.js');

  fs.writeFileSync(jsonSummaryPath, JSON.stringify(results, null, 2));
  fs.writeFileSync(jsonTimeSeriesPath, JSON.stringify(unifiedTimeSeries, null, 2));

  console.log(`\nComparative unification completed successfully and saved to:`);
  console.log(` - Summary: ${jsonSummaryPath}`);
  console.log(` - Unified TimeSeries: ${jsonTimeSeriesPath}`);
}

if (require.main === module) {
  runComparison();
}

module.exports = { runComparison };
